import {STATIONS} from './content.js';
import {audioPreferences, RadioAudio, Narrator} from './audio.js';

const SOURCE='https://docs.google.com/document/d/1trfmfnYYsE-dckNZu7Rl5sQ_vogv55G8wu2EsDUNUi0/edit';
const STORAGE='vnr202-radio-v1';
const paths={radio:'M8 8a6 6 0 0 0 0 8M16 8a6 6 0 0 1 0 8M4 4a12 12 0 0 0 0 16M20 4a12 12 0 0 1 0 16M12 11v10M11 10h2',arrow:'M5 12h14M13 6l6 6-6 6',back:'M19 12H5M11 6l-6 6 6 6',lock:'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5zM12 14v3',check:'M5 12l4 4L19 6',close:'M6 6l12 12M6 18L18 6',book:'M12 5C8 3 5 3 2 4v15c3-1 6-1 10 1 4-2 7-2 10-1V4c-3-1-6-1-10 1zm0 0v15',award:'M12 2l3 3 4 1-1 5-2 3-4 2-4-2-2-3-1-5 4-1zM8 16l-1 6 5-3 5 3-1-6',volume:'M11 5L6 9H2v6h4l5 4zM15 8a6 6 0 0 1 0 8M18 4a11 11 0 0 1 0 16',muted:'M11 5L6 9H2v6h4l5 4zM16 9l6 6M16 15l6-6',motion:'M3 7h12M3 12h8M3 17h4M16 11l5 5-5 5',menu:'M4 6h16M4 12h16M4 18h16',play:'M8 5l11 7-11 7z',stop:'M6 6h12v12H6z',info:'M12 16v-5M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',key:'M9 14a6 6 0 1 1 4-4l8 8-3 3-2-2-2 2-3-3'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.radio}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,action='',extra='',secondary=false)=>`<button class="button${secondary?' secondary':''}" data-action="${action}" ${extra}>${label}</button>`;
const chip=(label,cls='')=>`<span class="chip ${cls}">${label}</span>`;
const wave=(n=48)=>`<div class="waveform" aria-hidden="true">${Array.from({length:n},(_,i)=>`<i style="height:${5+Math.abs(Math.sin(i*.67)*Math.cos(i*.21))*30}px;--delay:-${(i*.13).toFixed(2)}s"></i>`).join('')}</div>`;
const signal=f=>`<div class="signal"><span class="signal-status"><i class="signal-dot"></i>TÍN HIỆU ỔN ĐỊNH</span><span>${esc(f)} MHz</span></div>`;
const radar=()=>`<div class="radar" aria-hidden="true"><div class="radar-disc"><div class="radar-ring"></div><div class="radar-sweep"></div>${[1,2,3,4].map(i=>`<i class="radar-point p${i}"></i>`).join('')}</div></div>`;
function fresh(){return {version:1,solved:STATIONS.map(s=>s.questions.map(()=>false)),tries:STATIONS.map(s=>s.questions.map(()=>0)),...audioPreferences(),reduced:false};}
function readSave(){try{const s=JSON.parse(localStorage.getItem(STORAGE));if(s?.version===1&&Array.isArray(s.solved)&&s.solved.length===4&&s.solved.every((v,i)=>Array.isArray(v)&&v.length===STATIONS[i].questions.length)){const f=fresh();f.solved=s.solved.map(v=>v.map(x=>x===true));f.tries=f.tries.map((v,i)=>v.map((_,j)=>Math.max(0,Number(s.tries?.[i]?.[j])||0)));Object.assign(f,audioPreferences(s));f.reduced=!!s.reduced;return f;}}catch{}return fresh();}
let saved=readSave();
let route=location.hash.slice(1)||'home',stage=0,qi=0,selected=null,feedback=null,checking=false,recentKey=null,expanded=false,notebookFilter=-1,speaking=false,autoNarrationTimer=null,toastTimer=null;
let generation=0;
const main=document.querySelector('#main');
const total=()=>saved.solved.flat().filter(Boolean).length;
const solvedCount=i=>saved.solved[i].filter(Boolean).length;
const complete=i=>saved.solved[i].every(Boolean);
const unlocked=i=>i===0||complete(i-1);
const firstPending=i=>Math.max(0,saved.solved[i].findIndex(x=>!x));
const nextStation=()=>{const i=STATIONS.findIndex((_,n)=>!complete(n));return i<0?3:i;};
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(saved));}catch{toast('Trình duyệt không cho lưu tiến độ. Bạn vẫn có thể chơi trong phiên này.');}}
function toast(message){const t=document.querySelector('#toast');clearTimeout(toastTimer);t.textContent=message;t.classList.add('visible');toastTimer=setTimeout(()=>t.classList.remove('visible'),3600);}
function stopSpeech(){clearTimeout(autoNarrationTimer);autoNarrationTimer=null;narrator.stop();speaking=false;}
function routeTo(to,replace=false){stopSpeech();generation++;checking=false;route=to;history[replace?'replaceState':'pushState']({},'',`#${to}`);render();window.scrollTo({top:0,behavior:'instant'});document.querySelector('.site-header').classList.remove('menu-open');document.querySelector('[data-action=menu]').setAttribute('aria-expanded','false');main.focus({preventScroll:true});}
function enterStation(i){if(!Number.isInteger(i)||i<0||i>3)return;if(!unlocked(i)){toast('Hoàn thành trạm trước để nhận tín hiệu này.');return;}qi=firstPending(i);stage=i;selected=null;feedback=saved.solved[i][qi]?'correct':null;recentKey=null;expanded=false;routeTo(`station/${i+1}`);if(saved.sound)morseTone();}
function getRoute(){const raw=location.hash.slice(1)||'home';const m=/^(station|result)\/([1-4])$/.exec(raw);if(m){const i=Number(m[2])-1;if(!unlocked(i)||(m[1]==='result'&&!complete(i)))return 'missions';stage=i;qi=firstPending(i);selected=null;feedback=saved.solved[i][qi]?'correct':null;return raw;}return ['home','missions','notebook'].includes(raw)?raw:'home';}
function card(i){const s=STATIONS[i],open=unlocked(i),done=complete(i),count=solvedCount(i);return `<article class="station-card ${done?'complete':open?'available':'locked'}"><div class="station-card-top"><span>TRẠM 0${i+1}</span>${icon(done?'check':open?'arrow':'lock')}</div><p class="station-period">${s.period}</p><h3>${esc(s.title)}</h3><p class="station-description">${esc(s.description)}</p><div class="station-card-bottom"><p class="mono">${String(s.questions.length).padStart(2,'0')} KHÓA GIẢI MÃ${count?` · ĐÃ MỞ ${count}`:''}</p><button class="text-button" data-action="station" data-stage="${i}" ${open?'':'disabled'}>${done?'Xem lại nhiệm vụ':open?(count?'Tiếp tục giải mã':'Nhận nhiệm vụ'):'Mở sau khi hoàn thành trạm trước'} ${open?icon('arrow'):''}</button></div></article>`;}
function home(){return `<div class="page page-enter"><section class="hero"><div class="hero-copy">${chip('TÍN HIỆU TỪ QUÁ KHỨ')}<h1>Lịch sử đang<br>chờ bạn giải mã.</h1><p>Nhập vai chiến sĩ cơ mật. Kết nối 4 trạm vô tuyến, giải những bức điện lịch sử và chinh phục VNR202.</p><div class="actions">${button(total()?'Tiếp tục hành trình '+icon('arrow'):'Bắt đầu nhận tín hiệu '+icon('arrow'),'missions')}${button('Cách chơi','how','',true)}</div><div class="home-audio"><button class="text-button pref-button" data-action="home-sound"></button><p class="audio-status" id="home-audio-status" aria-live="polite"></p></div><div class="hero-stats mono"><b>04 TRẠM LỊCH SỬ</b><span>15 KHÓA GIẢI MÃ</span><span>1920 — 1975</span></div></div><div class="radio-terminal">${signal('1930.02')}${radar()}<div class="incoming-paper"><div class="letter-meta"><span>ĐIỆN KHẨN / SỐ 001</span><span class="stamp">BẢO MẬT</span></div><h2>Từ Hương Cảng,<br>một tín hiệu đang chờ…</h2><p class="mono">[ KHÓA 1.1 ] · [ KHÓA 1.2 ] · [ KHÓA 1.3 ]</p></div>${wave()}<p class="morse">• – • / – • – / • • – &nbsp; KẾT NỐI ĐÃ SẴN SÀNG</p><div class="terminal-scanline"></div></div></section><div class="divider"></div><section class="section-space"><div class="section-heading"><div><p class="eyebrow">HÀNH TRÌNH 1920 — 1975</p><h2>Bốn trạm. Một dòng chảy lịch sử.</h2></div><a class="text-button" href="#missions">Xem hành trình ↗</a></div><div class="station-grid">${STATIONS.map((_,i)=>card(i)).join('')}</div></section><section class="how-to" id="how-to" aria-label="Cách chơi">${[['01','Nhận điện mật','Chọn trạm và đọc bức điện bị mã hóa.'],['02','Tìm chìa khóa','Chọn đáp án, xác nhận và hiểu rõ sự kiện lịch sử.'],['03','Mở khóa tư liệu','Giải mã bức điện, nghe lời đọc và lưu vào sổ tay.']].map(([n,t,d])=>`<div><span class="mono">${n}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</section></div>`;}
function missions(){const next=nextStation(),all=total()===15;return `<div class="page page-enter"><header class="page-heading"><p class="eyebrow">HỒ SƠ NHIỆM VỤ</p><h1>Chọn trạm. Nối mạch lịch sử.</h1><p>Mỗi trạm là một giai đoạn. Giải mã trạm hiện tại để nhận tín hiệu tiếp theo.</p></header><section class="journey-summary"><div><p class="eyebrow">${total()?'HÀNH TRÌNH CỦA BẠN':'HỒ SƠ CHIẾN SĨ MỚI'}</p><h2>${all?'Tất cả tín hiệu đã được kết nối':total()?`Tín hiệu tiếp theo: ${esc(STATIONS[next].title)}`:'Hành trình bắt đầu từ Hương Cảng'}</h2><p class="mono">${STATIONS.filter((_,i)=>complete(i)).length}/4 TRẠM HOÀN THÀNH · ${total()}/15 KHÓA ĐÃ GIẢI</p></div><div class="progress-track" role="progressbar" aria-label="Tiến độ hành trình" aria-valuemin="0" aria-valuemax="15" aria-valuenow="${total()}"><div class="progress-fill" style="width:${total()/15*100}%"></div></div></section><div class="station-grid">${STATIONS.map((_,i)=>card(i)).join('')}</div><section class="mission-brief"><div><p class="eyebrow">${all?'HÀNH TRÌNH ĐÃ HOÀN THÀNH':`LỆNH TRIỆU TẬP / TRẠM 0${next+1}`}</p><h2>${all?'Mỗi bức điện, một điều để nhớ.':`Đồng chí, ${esc(STATIONS[next].title)} đang chờ.`}</h2><p>${all?'Đọc lại 8 tư liệu lịch sử trong Sổ tay tình báo để củng cố kiến thức VNR202.':`${esc(STATIONS[next].description)} Hoàn thành ${STATIONS[next].questions.length} khóa để mở tư liệu của trạm.`}</p></div>${button(all?'Mở Sổ tay tình báo '+icon('arrow'):'Vào trạm '+icon('arrow'),all?'notebook':'station',all?'':`data-stage="${next}"`)}</section><button class="text-button reset-link" data-action="reset">Bắt đầu lại hành trình trên thiết bị này</button></div>`;}
function telegram(i,{plain=false,animate=true}={}){const s=STATIONS[i];if(plain)return s.telegram.replace(/\[\s*🔒\s*KHÓA\s*([\d.]+)\s*\]/g,(_,id)=>s.questions.find(q=>q.id===id)?.key||'');return s.telegram.split(/(\[\s*🔒\s*KHÓA\s*[\d.]+\s*\])/g).map(part=>{const m=/KHÓA\s*([\d.]+)/.exec(part);if(!m)return esc(part);const n=s.questions.findIndex(q=>q.id===m[1]);if(n<0)return esc(part);const q=s.questions[n],done=saved.solved[i][n],just=animate&&!saved.reduced&&!matchMedia('(prefers-reduced-motion:reduce)').matches&&recentKey===q.id;if(done){const word=just?[...q.key].map((c,j)=>`<i style="--delay:${Math.min(j*.018,.6)}s">${esc(c)}</i>`).join(''):esc(q.key);return `<mark class="decoded-key${just?' just-opened':''}" data-key="${q.id}">${word}</mark>`;}return `<span class="lock-token${qi===n?' active':''}" data-key="${q.id}">${icon('lock')} KHÓA ${q.id} / CHƯA GIẢI MÃ</span>`;}).join('');}
function paper(i){const s=STATIONS[i];return `<article class="paper" aria-label="Bức điện mật trạm ${esc(s.title)}"><div class="paper-meta"><span>TRUNG ƯƠNG / ĐIỆN SỐ 00${i+1}</span>${chip('BẢO MẬT')}</div><p class="paper-place">NƠI PHÁT: ${esc(s.place.toUpperCase())}</p><p class="paper-greeting">Gửi chiến sĩ cơ mật,</p><div class="telegram-body" aria-live="polite">${telegram(i)}</div><p class="paper-end">${complete(i)?'KẾT THÚC ĐIỆN / ĐÃ XÁC THỰC':'KẾT THÚC ĐIỆN / CHỜ XÁC THỰC'}</p></article>`;}
function questionPanel(){const s=STATIONS[stage],q=s.questions[qi],done=saved.solved[stage][qi],choice=done?q.correct:selected;return `<section class="question-panel question-step" id="question-panel" aria-labelledby="question-title"><div class="question-top"><span>BẢNG GIẢI MÃ</span><span>KHÓA ${q.id}</span></div><h2 class="question-title" id="question-title">${esc(q.question)}</h2><p class="question-counter">CÂU ${qi+1}/${s.questions.length} · CHỌN MỘT ĐÁP ÁN</p><fieldset class="options" ${done||checking?'disabled':''} aria-label="Các đáp án">${q.options.map((a,i)=>`<label class="option${choice===i?' selected':''}${done&&q.correct===i?' correct disabled':''}${done?' disabled':''}${feedback==='incorrect'&&choice===i?' incorrect':''}"><input type="radio" name="answer" value="${i}" ${choice===i?'checked':''} ${done||checking?'disabled':''}><span class="option-letter">${'ABCD'[i]}</span><span class="option-label">${esc(a)}</span>${done&&i===q.correct?icon('check'):feedback==='incorrect'&&choice===i?icon('close'):''}</label>`).join('')}</fieldset>${done?`<div class="answer-feedback" role="status"><h3>${icon('check')}Chính xác. Khóa ${q.id} đã được mở.</h3><p>${esc(q.explanation)}</p><p class="feedback-source">ĐỐI CHIẾU: TÀI LIỆU ÔN TẬP VNR202 · TRẠM 0${stage+1}</p></div>`:feedback==='incorrect'?`<div class="answer-feedback error" role="alert"><h3>${icon('info')}Tín hiệu chưa khớp. Hãy thử lại.</h3><p>Đọc lại bức điện và chọn một đáp án khác. Mỗi lần giải mã là một lần ghi nhớ — không giới hạn số lần thử.</p></div>`:''}${done?button(qi===s.questions.length-1?'Hoàn thành trạm '+icon('arrow'):'Tiếp tục giải mã '+icon('arrow'),'next'):button(checking?'<span class="spinner"></span>Đang xác thực…':'Xác nhận giải mã '+icon('arrow'),'confirm',`${selected===null||checking?'disabled':''} aria-busy="${checking}"`)}<p class="question-help">${done?'Từ khóa đã được điền vào bức điện.':checking?'Đang đối chiếu tín hiệu…':'Không giới hạn thời gian. Ưu tiên hiểu đúng.'} <span class="desktop-shortcut">${done?'':'Phím 1–4 để chọn, Enter để xác nhận.'}</span></p></section>`;}
function game(){const s=STATIONS[stage],count=solvedCount(stage);return `<div class="page console-page page-enter"><div class="console-tools"><button class="text-button" data-action="missions">${icon('back')} Chọn trạm</button><div class="console-preferences"><button class="text-button pref-button" data-action="sound" aria-pressed="${saved.sound}">${icon(saved.sound?'volume':'muted')}Âm thanh: ${saved.sound?'Bật':'Tắt'}</button><button class="text-button pref-button motion-pref" data-action="motion" aria-label="Giảm chuyển động" aria-pressed="${saved.reduced}" title="Giảm chuyển động">${icon('motion')}Giảm chuyển động</button></div></div><div class="console-title"><div><p class="eyebrow">HÀNH TRÌNH / TRẠM 0${stage+1}</p><h1>Trạm tín hiệu ${esc(s.title)}</h1><p class="console-period">${s.period}</p></div><div class="console-progress">${chip(`${count}/${s.questions.length} KHÓA ĐÃ MỞ`)}<div class="progress-track" role="progressbar" aria-label="Tiến độ trạm" aria-valuemin="0" aria-valuemax="${s.questions.length}" aria-valuenow="${count}"><div class="progress-fill" style="width:${count/s.questions.length*100}%"></div></div><div class="key-indicators" aria-hidden="true">${s.questions.map((_,i)=>`<span class="${saved.solved[stage][i]?'done':''}"></span>`).join('')}</div></div></div><div class="console-grid"><div class="telegram-column${expanded?' expanded':''}">${signal(s.frequency)}${paper(stage)}<button class="text-button mobile-telegram-toggle" data-action="expand" aria-expanded="${expanded}">${expanded?'Thu gọn điện mật ↑':'Đọc toàn bộ điện mật ↓'}</button><p class="telegram-note">${icon('lock')}Mỗi câu trả lời đúng sẽ mở một khóa trong bức điện.</p></div>${questionPanel()}</div><aside class="console-bottom"><div><p class="eyebrow">SỔ TAY TÌNH BÁO</p><p>${complete(stage)?'Hai tư liệu của trạm đã được mở. Đọc lại để ghi nhớ.':'Hoàn thành trạm để mở 2 tư liệu lịch sử và huy hiệu học tập.'}</p></div><button class="text-button" data-action="notebook">Xem sổ tay ↗</button></aside></div>`;}
function result(){const s=STATIONS[stage],all=total()===15;return `<div class="page result-page page-enter"><div class="emblem" aria-hidden="true">${icon('award')}</div>${chip(all?'HÀNH TRÌNH / HOÀN THÀNH':`TRẠM 0${stage+1} / HOÀN THÀNH`)}<h1>Tín hiệu đã thông.<br>Lịch sử đã được mở khóa.</h1><p class="result-description">Bạn đã giải mã thành công bức điện từ ${esc(s.title)}.<br>Hai tư liệu lịch sử vừa được thêm vào Sổ tay tình báo.</p><div class="result-stats"><div><strong>${s.questions.length}/${s.questions.length}</strong><span>KHÓA ĐÃ GIẢI</span></div><div><strong>02</strong><span>TƯ LIỆU MỞ KHÓA</span></div><div><strong>${STATIONS.filter((_,i)=>complete(i)).length}/4</strong><span>TRẠM HOÀN THÀNH</span></div></div><section class="audio-card${speaking?' speaking':''}">${button(icon(speaking?'stop':'play'),'speak',`aria-label="${speaking?'Dừng đọc':'Nghe bức điện hoàn chỉnh'}"`)}<div><h3>Lắng nghe bức điện hoàn chỉnh</h3><p>LỜI TRUYỀN TIN / TRẠM ${esc(s.title.toUpperCase())}</p></div>${wave(16)}</section>${narrationControls()}<button class="text-button" data-action="transcript">Đọc bản chép lời ↗</button><div class="result-actions">${button('Mở Sổ tay tình báo '+icon('arrow'),'notebook')}${button(stage<3?'Đến trạm tiếp theo '+icon('arrow'):'Xem lại hành trình '+icon('arrow'),stage<3?'station':'missions',stage<3?`data-stage="${stage+1}"`:'',true)}</div>${all?'<p class="question-help">Hoàn thành 15/15 khóa · 8 tư liệu đã mở · Tiếp tục ôn tập trong Sổ tay tình báo.</p>':''}</div>`;}
function notebook(){const unlockedDocs=STATIONS.filter((_,i)=>complete(i)).length*2;const docs=STATIONS.flatMap((s,i)=>complete(i)&&(notebookFilter<0||notebookFilter===i)?s.documents.map((d,j)=>({d,i,j})):[]);return `<div class="page page-enter notebook-layout"><aside class="notebook-sidebar"><p class="eyebrow">HỒ SƠ HỌC TẬP</p><h2>Sổ tay<br>tình báo</h2><div class="divider"></div>${chip(`${String(unlockedDocs).padStart(2,'0')} TƯ LIỆU ĐÃ MỞ`)}<div class="notebook-filters" aria-label="Lọc tư liệu"><button class="text-button ${notebookFilter<0?'active':''}" data-action="filter" data-filter="-1">Tất cả tư liệu</button>${STATIONS.map((s,i)=>`<button class="text-button ${notebookFilter===i?'active':''}" data-action="filter" data-filter="${i}" ${complete(i)?'':'disabled'}>Trạm 0${i+1} · ${complete(i)?esc(s.title):'Chưa mở'}</button>`).join('')}</div>${unlockedDocs?`<div class="notebook-badge">${icon('award')}<h3>${total()===15?'Người kết nối dòng chảy lịch sử':'Người kết nối tín hiệu đầu tiên'}</h3><p>HUY HIỆU HỌC TẬP · ${STATIONS.filter((_,i)=>complete(i)).length}/4 TRẠM</p></div>`:''}</aside><section class="notebook-content"><header class="page-heading"><p class="eyebrow">KHO TƯ LIỆU LỊCH SỬ</p><h1>Mỗi bức điện,<br>một điều để nhớ.</h1><p>Đọc lại văn kiện, kết nối sự kiện và củng cố kiến thức VNR202.</p></header>${docs.length?`<div class="document-grid">${docs.map(({d,i,j})=>`<button class="document-card" data-action="document" data-stage="${i}" data-doc="${j}"><span class="document-cover"><span class="stamp">HỒ SƠ ĐÃ GIẢI MẬT</span><h2>${esc(d.title.replace(/\s*\([^)]*\)\s*$/,''))}</h2><span class="mono">${esc(STATIONS[i].period)}</span></span><span class="eyebrow">TƯ LIỆU / TRẠM 0${i+1}</span><h3>${esc(d.title)}</h3><span class="text-button">Mở hồ sơ ↗</span></button>`).join('')}</div>`:`<div class="empty-notebook">${icon('book')}<h2>Tư liệu đang chờ được giải mật.</h2><p>Hoàn thành các khóa của trạm Hương Cảng để mở hai tư liệu đầu tiên: Đường cách mệnh và Cương lĩnh chính trị đầu tiên.</p>${button('Nhận nhiệm vụ đầu tiên '+icon('arrow'),'station','data-stage="0"')}</div>`}${unlockedDocs<8?`<div class="locked-docs">${icon('lock')}<div><h3>Còn ${8-unlockedDocs} tư liệu chưa được mở</h3><p>Hoàn thành trạm tiếp theo để nhận tư liệu và huy hiệu mới. Tiến độ được lưu trên trình duyệt này.</p></div></div>`:''}<p class="question-help">Tư liệu là nội dung tóm lược theo tài liệu dự án, không phải bản scan gốc.</p></section></div>`;}
function render(){document.documentElement.classList.toggle('reduce-motion',saved.reduced);const current=route.startsWith('station/')||route.startsWith('result/')?'missions':route;document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=`${route.startsWith('station/')?STATIONS[stage].title+' · ':route==='notebook'?'Sổ tay tình báo · ':''}Trạm Liên Lạc Bí Mật · VNR202`;main.innerHTML=route==='home'?home():route==='missions'?missions():route==='notebook'?notebook():route.startsWith('result/')?result():game();main.querySelectorAll('.question-panel>.button').forEach(b=>b.classList.add('full'));radioAudio.setAmbient(route==='home'||route.startsWith('station/'));updateAudioUI();updateVoiceChoices();}
function refreshQuestion(){const panel=document.querySelector('#question-panel');if(panel){panel.outerHTML=questionPanel();document.querySelector('.question-panel>.button')?.classList.add('full');}}
function choose(value){if(!route.startsWith('station/')||checking||saved.solved[stage][qi])return;selected=value;feedback=null;recentKey=null;refreshQuestion();}
async function confirm(){if(selected===null||checking||saved.solved[stage][qi])return;const q=STATIONS[stage].questions[qi],s=stage,n=qi,ticket=generation;checking=true;refreshQuestion();await new Promise(r=>setTimeout(r,saved.reduced?30:380));if(ticket!==generation){checking=false;return;}checking=false;saved.tries[s][n]++;if(selected===q.correct){saved.solved[s][n]=true;feedback='correct';recentKey=q.id;persist();render();if(saved.sound)tone('success');document.querySelector('.answer-feedback')?.setAttribute('tabindex','-1');document.querySelector('.answer-feedback')?.focus({preventScroll:true});}else{feedback='incorrect';persist();refreshQuestion();if(saved.sound)tone('error');document.querySelector('.answer-feedback')?.setAttribute('tabindex','-1');document.querySelector('.answer-feedback')?.focus({preventScroll:true});}}
function next(){if(!saved.solved[stage][qi])return;if(qi===STATIONS[stage].questions.length-1){routeTo(`result/${stage+1}`);celebrate();if(saved.sound){tone('success');const resultRoute=route;autoNarrationTimer=setTimeout(()=>{autoNarrationTimer=null;if(route===resultRoute&&saved.sound&&!document.hidden)speak();},850);}return;}qi++;selected=null;feedback=saved.solved[stage][qi]?'correct':null;recentKey=null;render();if(matchMedia('(max-width:800px)').matches)document.querySelector('#question-panel')?.scrollIntoView({block:'start',behavior:saved.reduced?'instant':'smooth'});}
function showDialog(markup){stopSpeech();document.querySelector('#dialog-content').innerHTML=markup;document.querySelector('#document-dialog').showModal();}
function readDoc(s,n){if(!complete(s)){toast('Hãy hoàn thành trạm để mở tư liệu này.');return;}const d=STATIONS[s].documents[n];if(!d)return;showDialog(`<p class="eyebrow">SỔ TAY TÌNH BÁO / TRẠM 0${s+1}</p><h2 id="dialog-title">${esc(d.title)}</h2><p>${esc(d.body)}</p><p class="modal-source">Nội dung tóm lược theo <a href="${SOURCE}" target="_blank" rel="noopener noreferrer">tài liệu dự án VNR202</a>. Đây không phải bản scan gốc.</p>`);}
function tone(kind){radioAudio.tone(kind);}
function morseTone(){radioAudio.morse();}
function narrationText(){return `Tín hiệu từ trạm ${STATIONS[stage].title} đã được giải mã. Đồng chí hãy cùng lắng nghe bức điện hoàn chỉnh. ${telegram(stage,{plain:true})}`;}
function narrationControls(){return `<div class="narration-controls"><label>Giọng đọc<select id="narration-voice" aria-label="Giọng đọc tổng kết"><option value="auto">Tự chọn giọng tiếng Việt phù hợp</option></select></label><label>Cách đọc<select id="narration-style" aria-label="Cách đọc tổng kết"><option value="natural" ${saved.narrationStyle==='natural'?'selected':''}>Kể chuyện tự nhiên</option><option value="broadcast" ${saved.narrationStyle==='broadcast'?'selected':''}>Truyền tin trang trọng</option></select></label><p class="narration-hint" id="narration-hint"></p></div>`;}
function updateVoiceChoices(){const select=document.querySelector('#narration-voice');if(!select)return;const voices=narrator.voices();const signature=voices.map(v=>v.voiceURI||v.name).join('|');if(select.dataset.voices!==signature){select.innerHTML='<option value="auto">Tự chọn giọng tiếng Việt phù hợp</option>'+voices.map(v=>`<option value="${esc(v.voiceURI||v.name)}">${esc(v.name)}</option>`).join('');select.dataset.voices=signature;}select.value=voices.some(v=>(v.voiceURI||v.name)===saved.voice)?saved.voice:'auto';const chosen=voices.find(v=>(v.voiceURI||v.name)===saved.voice)||voices[0];const hint=document.querySelector('#narration-hint');if(hint)hint.textContent=chosen?`Giọng ${chosen.name} · Có nhịp nghỉ giữa các câu. Bạn có thể đổi giọng trước khi nghe.`:'Chất giọng phụ thuộc bộ giọng tiếng Việt trên thiết bị. Có nhịp nghỉ giữa các câu.';}
function updateAudioUI(){const enabled=saved.sound;const globalButton=document.querySelector('#global-sound');if(globalButton){globalButton.innerHTML=icon(enabled?'volume':'muted');globalButton.setAttribute('aria-pressed',String(enabled));globalButton.setAttribute('aria-label',enabled?'Tắt âm thanh toàn trang':'Bật âm thanh toàn trang');globalButton.title=enabled?'Âm thanh: Bật':'Âm thanh: Tắt';globalButton.dataset.audioActive=String(radioAudio.ready);}const gameButton=document.querySelector('.console-preferences [data-action="sound"]');if(gameButton){gameButton.innerHTML=icon(enabled?'volume':'muted')+'Âm thanh: '+(enabled?'Bật':'Tắt');gameButton.setAttribute('aria-pressed',String(enabled));}const homeButton=document.querySelector('[data-action="home-sound"]');if(homeButton){homeButton.innerHTML=icon(enabled&&radioAudio.ready?'volume':'muted')+(enabled&&radioAudio.ready?'Tắt tiếng vô tuyến':'Nghe tiếng vô tuyến');homeButton.setAttribute('aria-pressed',String(enabled&&radioAudio.ready));}const status=document.querySelector('#home-audio-status');if(status)status.textContent=!enabled?'Âm thanh đang tắt.':radioAudio.ready?'Tín hiệu Morse đang phát nhẹ tại trang chủ.':'Bấm hoặc chạm để nghe tiếng vô tuyến.';}
function updateNarrationUI(){const card=document.querySelector('.audio-card');if(!card)return;card.classList.toggle('speaking',speaking);const play=card.querySelector('[data-action="speak"]');if(play){play.innerHTML=icon(speaking?'stop':'play');play.setAttribute('aria-label',speaking?'Dừng đọc':'Nghe bức điện hoàn chỉnh');}}
function toggleSound(){saved.sound=!saved.sound;saved.audioVersion=2;if(!saved.sound)stopSpeech();radioAudio.setEnabled(saved.sound);if(saved.sound)radioAudio.activate();persist();updateAudioUI();}
function speak(){clearTimeout(autoNarrationTimer);autoNarrationTimer=null;if(speaking){stopSpeech();return;}if(!saved.sound){saved.sound=true;saved.audioVersion=2;radioAudio.setEnabled(true);persist();}radioAudio.activate();narrator.play(narrationText(),{voice:saved.voice,style:saved.narrationStyle});}
function celebrate(){if(saved.reduced||matchMedia('(prefers-reduced-motion:reduce)').matches)return;const c=document.createElement('div');c.className='confetti';c.setAttribute('aria-hidden','true');c.innerHTML=Array.from({length:35},(_,i)=>`<i style="--x:${(i*29)%100}%;--delay:${(i%7)*.08}s"></i>`).join('');document.body.append(c);setTimeout(()=>c.remove(),3000);}
const actionHandlers={missions:()=>routeTo('missions'),notebook:()=>routeTo('notebook'),station:e=>enterStation(Number(e.dataset.stage)),confirm,next,how:()=>document.querySelector('#how-to')?.scrollIntoView({behavior:saved.reduced?'instant':'smooth'}),sound:toggleSound,'home-sound':()=>{if(saved.sound&&!radioAudio.ready)radioAudio.activate();else toggleSound();},motion:()=>{saved.reduced=!saved.reduced;persist();render();toast(saved.reduced?'Đã bật chế độ giảm chuyển động.':'Đã bật hiệu ứng chuyển động.');},expand:()=>{expanded=!expanded;document.querySelector('.telegram-column')?.classList.toggle('expanded',expanded);const b=document.querySelector('[data-action=expand]');b.setAttribute('aria-expanded',String(expanded));b.textContent=expanded?'Thu gọn điện mật ↑':'Đọc toàn bộ điện mật ↓';},filter:e=>{notebookFilter=Number(e.dataset.filter);render();},document:e=>readDoc(Number(e.dataset.stage),Number(e.dataset.doc)),speak,transcript:()=>showDialog(`<p class="eyebrow">ĐIỆN ĐÃ GIẢI MÃ / TRẠM 0${stage+1}</p><h2 id="dialog-title">Bức điện từ ${esc(STATIONS[stage].title)}</h2><p>${esc(narrationText())}</p><p class="modal-source">Lời đọc được tạo bằng tính năng đọc văn bản của trình duyệt, không phải bản ghi âm lịch sử.</p>`),about:()=>showDialog(`<p class="eyebrow">VNR202 / FPT UNIVERSITY</p><h2 id="dialog-title">Học lịch sử qua từng tín hiệu.</h2><p>Trạm Liên Lạc Bí Mật là trò chơi ôn tập Lịch sử Đảng Cộng sản Việt Nam, gồm 4 trạm, 15 câu hỏi và 8 tư liệu trong giai đoạn 1920–1975.</p><p>Trả lời đúng để mở từ khóa trong điện mật. Hoàn thành trạm để mở tư liệu và nhận tín hiệu tiếp theo. Bạn có thể bật âm thanh hoặc giảm chuyển động khi chơi.</p><p>Tiến độ được lưu trên trình duyệt của bạn. Đổi thiết bị hoặc xóa dữ liệu trình duyệt sẽ không giữ lại tiến độ.</p><p class="modal-source">Nội dung theo <a href="${SOURCE}" target="_blank" rel="noopener noreferrer">tài liệu dự án</a>. Huy hiệu ghi nhận tiến độ trong trò chơi, không phải chứng nhận hoàn thành môn học.</p>`),menu:()=>{const open=document.querySelector('.site-header').classList.toggle('menu-open');document.querySelector('[data-action=menu]').setAttribute('aria-expanded',String(open));},reset:()=>showDialog(`<p class="eyebrow">HÀNH TRÌNH MỚI</p><h2 id="dialog-title">Bắt đầu lại từ Hương Cảng?</h2><p>Tiến độ 15 khóa và các tư liệu đã mở trên trình duyệt này sẽ được đặt lại.</p>${button('Bắt đầu lại','reset-confirm')}`),'reset-confirm':()=>{document.querySelector('#document-dialog').close();saved=fresh();radioAudio.setEnabled(saved.sound);radioAudio.activate();persist();selected=null;feedback=null;stage=0;qi=0;routeTo('missions');toast('Đã sẵn sàng cho một hành trình mới.');}};
const radioAudio=new RadioAudio({onState:()=>updateAudioUI()});
const narrator=new Narrator({synth:window.speechSynthesis,Utterance:window.SpeechSynthesisUtterance,onState:active=>{speaking=active;radioAudio.setSpeaking(active);updateNarrationUI();},onError:error=>toast(error==='unsupported'?'Trình duyệt chưa hỗ trợ đọc văn bản. Hãy xem bản chép lời.':'Chưa phát được lời đọc. Bạn có thể bấm Nghe để thử lại hoặc mở bản chép lời.')});
window.speechSynthesis?.addEventListener('voiceschanged',updateVoiceChoices);
function unlockAudio(event){if(!event.isTrusted||!saved.sound)return;if(event.type==='keydown'&&['Shift','Control','Alt','Meta'].includes(event.key))return;if(event.target.closest?.('[data-action="sound"],[data-action="home-sound"]'))return;radioAudio.activate();}
document.addEventListener('pointerdown',unlockAudio,{capture:true,passive:true});
document.addEventListener('keydown',unlockAudio,{capture:true});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSpeech();radioAudio.setVisible(!document.hidden);});
addEventListener('pageshow',()=>radioAudio.setVisible(!document.hidden));
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a&&!a.disabled)actionHandlers[a.dataset.action]?.(a);const link=e.target.closest('a[href^="#"]');if(link&&link.getAttribute('href')!=='#main'){e.preventDefault();routeTo(link.getAttribute('href').slice(1));}});
document.addEventListener('change',e=>{if(e.target.matches('input[name=answer]'))choose(Number(e.target.value));else if(e.target.matches('#narration-voice,#narration-style')){stopSpeech();if(e.target.id==='narration-voice')saved.voice=e.target.value;else saved.narrationStyle=e.target.value;persist();updateVoiceChoices();}});
document.addEventListener('keydown',e=>{if(!route.startsWith('station/')||document.querySelector('dialog[open]')||e.altKey||e.ctrlKey||e.metaKey)return;if(/^[1-4]$/.test(e.key)){e.preventDefault();choose(Number(e.key)-1);document.querySelector(`input[value="${Number(e.key)-1}"]`)?.focus();}else if(e.key==='Enter'&&!e.target.closest('button,a')){e.preventDefault();saved.solved[stage][qi]?next():confirm();}});
addEventListener('popstate',()=>{stopSpeech();generation++;route=getRoute();checking=false;selected=null;recentKey=null;feedback=saved.solved[stage][qi]?'correct':null;render();});
addEventListener('pagehide',()=>{stopSpeech();radioAudio.setVisible(false);});
document.querySelector('#brand-mark').innerHTML=icon('radio');document.querySelector('[data-action=menu]').innerHTML=icon('menu');
radioAudio.setEnabled(saved.sound);route=getRoute();feedback=saved.solved[stage][qi]?'correct':null;render();
